<script setup lang="ts">
import {onUnmounted,ref,watch} from 'vue';import {api} from '../api';import type {ScanTask} from '../types';import {useAuth} from '../composables/auth';import Button from './ui/Button.vue';import CatalogPagination from './CatalogPagination.vue';import StatusBadge from './StatusBadge.vue';
const props=defineProps<{task:ScanTask;revision?:number}>();const {canOperate}=useAuth();const page=ref(1),total=ref(0);const rows=ref<ScanTask[]>([]),loading=ref(false),creating=ref(false),error=ref(''),created=ref<number>();let generation=0;
async function load(requested=page.value){const gen=++generation;loading.value=true;error.value='';try{const values=await api.sdkOperations(props.task.id,requested);if(gen===generation){rows.value=values.items;page.value=values.page;total.value=values.total;}}catch(e){if(gen===generation)error.value='SDK 操作历史读取失败：'+(e as Error).message;}finally{if(gen===generation)loading.value=false;}}
watch(()=>[props.task.id,props.revision],()=>{rows.value=[];created.value=undefined;page.value=1;void load();},{immediate:true});onUnmounted(()=>generation++);
async function preflight(){if(creating.value||!canOperate.value)return;const id=props.task.id;creating.value=true;error.value='';try{const value=await api.createSDKOperation(id,{kind:'preflight'});if(id!==props.task.id)return;created.value=value.id;await load(1);}catch(e){if(id===props.task.id)error.value='SDK 预检创建失败：'+(e as Error).message;}finally{if(id===props.task.id)creating.value=false;}}
</script>
<template>
 <section class="sdk-operations" aria-label="SDK 操作历史"><header><h2>SDK 操作</h2><Button v-if="canOperate" size="sm" variant="outline" :loading="creating" @click="preflight">预检当前冻结配置</Button><Button size="sm" variant="ghost" :loading="loading" @click="load()">刷新 SDK 操作历史</Button></header>
  <p>预检不启动模型或扫描。独立复核从漏洞证据详情发起，使用独立执行身份并记录未知费用。</p><p v-if="error" role="alert" class="request-error">{{error}}</p><p v-if="created" role="status">已创建预检 <RouterLink :to="'/scans/'+created">#{{created}} · 查看预检执行</RouterLink>。</p>
  <p v-if="!loading&&!rows.length&&!error">尚无关联 SDK 操作。</p><div v-if="rows.length" class="operation-table"><table><thead><tr><th>操作 / 执行</th><th>状态</th><th>费用</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td><RouterLink :to="'/scans/'+row.id">{{row.sdkOperation?.kind==='validate'?'独立复核':'原生预检'}} #{{row.id}} / {{row.attempt||'等待领取'}}</RouterLink></td><td><StatusBadge :status="row.status"/></td><td>{{row.sdkOperation?.kind==='validate'?'未知 · SDK 未提供':'0 USD · 本地检查'}}</td></tr></tbody></table><CatalogPagination label="SDK 操作历史" :page="page" :page-size="50" :total="total" :loading="loading" @change="load"/></div>
 </section>
</template>
<style scoped>
.sdk-operations{border-top:1px solid var(--border-default);padding:var(--space-3) 0;margin:var(--space-3) 0;font-size:var(--font-size-xs);min-width:0}header{display:flex;flex-wrap:wrap;align-items:center;gap:var(--space-2)}h2{font-size:var(--font-size-sm);font-weight:var(--font-weight-semibold);margin:0}p{color:var(--text-secondary);margin:var(--space-2) 0;line-height:var(--line-height-body)}.operation-table{overflow:auto}table{border-collapse:collapse;width:100%;text-align:left}th,td{padding:var(--space-2);border-bottom:1px solid var(--border-subtle);white-space:nowrap}th{color:var(--text-secondary);font-weight:var(--font-weight-medium)}a{color:var(--accent-primary)}
</style>
